1	// Verificador somente leitura: hashes do manifesto, snapshots Git e arquivo ZIP.
2	import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {spawnSync} from 'node:child_process';
3	const sealPath=process.argv[2];assert(sealPath,'Informe packet-seal.json');
4	const seal=JSON.parse(fs.readFileSync(sealPath,'utf8')),dir=path.resolve(path.dirname(sealPath),seal.packetRelative);
5	const hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
6	assert.equal(hash(path.join(dir,'MANIFEST.json')),seal.manifestSHA256);
7	const manifest=JSON.parse(fs.readFileSync(path.join(dir,'MANIFEST.json'),'utf8'));
8	assert.equal(manifest.sha,seal.sha);let bytes=0;
9	for(const f of manifest.files){const p=path.resolve(dir,f.path);assert(p.startsWith(dir+path.sep));assert.equal(fs.statSync(p).size,f.bytes,f.path+' bytes');assert.equal(hash(p),f.sha256,f.path+' hash');bytes+=f.bytes;}
10	assert.equal(hash(import.meta.filename),hash(path.join(dir,'VERIFICADOR-SOMENTE-LEITURA.mjs.txt')),'Verificador difere da cópia selada');
11	const index=JSON.parse(fs.readFileSync(path.join(dir,'ARQUIVOS-REVISAO.json'),'utf8'));
12	let gitBindings=0;
13	for(const item of index){const result=spawnSync('git',['show',seal.sha+':'+item.path],{encoding:'utf8',maxBuffer:16*1024*1024});assert.equal(result.status,0,result.stderr);assert.equal(fs.readFileSync(path.join(dir,item.snapshot),'utf8'),result.stdout,item.path+' Git snapshot');gitBindings++}
14	if(seal.zipRelative)assert.equal(hash(path.resolve(path.dirname(sealPath),seal.zipRelative)),seal.zipSHA256,'ZIP');
15	console.log(JSON.stringify({status:'PASS',sha:seal.sha,files:manifest.files.length,bytes,gitBindings,manifestSHA256:seal.manifestSHA256,zipSHA256:seal.zipSHA256??null}));
16

