5	+++ b/components/operacoes-v4-preview/parts/FormalizarAprovacaoV4.tsx
6	@@ -0,0 +1,243 @@
7	+/**
8	+ * Operações V4 — "Formalizar aprovação pendente" (GOAL OPS-V4-FINANCEIRO-RETIRADA-GARANTIA-002,
9	+ * item D). Ação administrativa EXCEPCIONAL para OS com pagamento vigente sobre orçamento ainda
10	+ * não aprovado: conferência do escopo no servidor → motivo, declaração do responsável,
11	+ * evidência (opcional) e, se vencido, ratificação no momento atual → formalização. Tudo é
12	+ * revalidado no servidor (permissão de administrador, escopo, valores, concorrência); esta tela
13	+ * só mostra o que o servidor conferiu e envia a MESMA assinatura de escopo de volta.
14	+ * Preparar a ferramenta não autoriza usá-la em nenhuma OS real específica.
15	+ */
16	+"use client";
17	+
18	+import { useEffect, useRef, useState } from "react";
19	+import { C, card, cardTitle, fmt, upLabel } from "../tokens";
20	+import type { ConferenciaFormalizacaoUiV4, V4Vals } from "../use-v4-preview";
21	+import { gerarOperacaoIdV3 } from "@/lib/operacoes-v3/recebimento-misto-model";
22	+import {
23	+  MOTIVO_FORMALIZACAO_MIN_V3,
24	+  type EntradaFormalizacaoV3,
25	+  type EscopoFormalizacaoV3,
26	+  type LinhaEscopoFormalizacaoV3,
27	+} from "@/lib/operacoes-v3/formalizacao-aprovacao-model";
28	+
29	+const btnPrimary: React.CSSProperties = { height: 32, width: "100%", padding: "0 14px", border: "none", background: C.primary, color: C.white, borderRadius: 8, fontSize: 12.5, fontWeight: 600 };
30	+const btnGhost: React.CSSProperties = { height: 30, width: "100%", padding: "0 12px", border: `1px solid ${C.inputBd2}`, background: C.surface, color: C.body, borderRadius: 8, fontSize: 12, fontWeight: 500, cursor: "pointer" };
31	+const campo: React.CSSProperties = { width: "100%", padding: "7px 9px", border: `1px solid ${C.inputBd}`, borderRadius: 7, fontSize: 12.5, color: C.body, background: C.surface, fontFamily: "inherit" };
32	+
33	+type Conferido = Extract<ConferenciaFormalizacaoUiV4, { ok: true }>;
34	+
35	+const LANCAMENTO: Record<EscopoFormalizacaoV3["lancamentos"][number]["tipo"], string> = {
36	+  pagamento: "Pagamento",
37	+  liquidacao: "Liquidação",
38	+  estorno_pagamento: "Estorno",
39	+};
