43	+/** Linha como o cliente a vê: valor com desconto, cortesia, interna e alternativa não escolhida. */
44	+function textoLinha(l: LinhaEscopoFormalizacaoV3): string {
45	+  const nome = `${l.grupo ? `${l.grupo}: ` : ""}${l.descricao || (l.tipo === "peca" ? "Peça" : "Serviço")}${l.quantidade != null && l.quantidade !== 1 ? ` × ${l.quantidade}` : ""}`;
46	+  if (l.situacao === "cortesia") return `${nome} — cortesia`;
47	+  if (l.situacao === "interna") return `${nome} — interno (não exibido ao cliente)`;
48	+  if (l.situacao === "alternativa_nao_escolhida") return `${nome} — não escolhida (${centavos(l.valorCentavos)})`;
49	+  return `${nome} — ${centavos(l.valorCentavos)}`;
50	+}
51	+
52	+export function FormalizarAprovacaoV4({ v }: { v: V4Vals }) {
53	+  const f = v.formalizacao;
54	+  const [aberto, setAberto] = useState(false);
55	+  const [carregando, setCarregando] = useState(false);
56	+  const [enviando, setEnviando] = useState(false);
57	+  const [conferido, setConferido] = useState<Conferido | null>(null);
58	+  const [motivo, setMotivo] = useState("");
59	+  const [evidencia, setEvidencia] = useState("");
60	+  const [declaracao, setDeclaracao] = useState(false);
61	+  const [ratificar, setRatificar] = useState(false);
62	+  const [mensagem, setMensagem] = useState<string | null>(null);
63	+  const [feito, setFeito] = useState(false);
64	+  // Confirmação ENVIADA e ainda sem resultado definitivo (incerto/não conferido): reenviada
65	+  // byte a byte (mesma chave, mesmo conteúdo) — os campos ficam travados enquanto existir.
66	+  const [pendente, setPendente] = useState<EntradaFormalizacaoV3 | null>(null);
67	+  // Identidade desta conferência: nova a cada conferência.
68	+  const operacaoId = useRef<string | null>(null);
69	+  const envio = useRef(false);
70	+  const ativo = useRef(true);
71	+  useEffect(() => {
72	+    ativo.current = true;
73	+    return () => {
74	+      ativo.current = false;
75	+    };
76	+  }, []);
77	+
78	+  if (!f?.disponivel && !feito) return null;
79	+
80	+  const conferir = async () => {
81	+    if (!f?.conferir || pendente) return;
82	+    setCarregando(true);
83	+    setMensagem(null);
84	+    try {
85	+      const r = await f.conferir();
86	+      if (!ativo.current) return;
87	+      if (r.ok) {
88	+        setConferido(r);
89	+        // Nova conferência = novo ato: declarações e ratificação são pedidas de novo.
90	+        setDeclaracao(false);
91	+        setRatificar(false);
92	+        operacaoId.current = gerarOperacaoIdV3();
93	+      } else if (r.code !== "fora_do_alvo") {
94	+        setConferido(null);
95	+        setMensagem(r.mensagem);
96	+      }
97	+    } finally {
98	+      if (ativo.current) setCarregando(false);
99	+    }
100	+  };
101	+
102	+  const abrir = () => {
103	+    setAberto(true);
104	+    setFeito(false);
105	+    void conferir();
106	+  };
107	+
108	+  const travado = enviando || !!pendente;
109	+  const motivoOk = motivo.trim().length >= MOTIVO_FORMALIZACAO_MIN_V3;
110	+  const podeFormalizar =
111	+    !!pendente || (!!conferido && !!operacaoId.current && motivoOk && declaracao && (!conferido.vencido || ratificar) && !enviando && !carregando);
112	+
113	+  const formalizar = async () => {
114	+    if (!podeFormalizar || envio.current || !f?.formalizar) return;
115	+    const entrada: EntradaFormalizacaoV3 | null =
116	+      pendente ??
117	+      (conferido && operacaoId.current
118	+        ? {
119	+            operacaoId: operacaoId.current,
120	+            motivo,
121	+            declaracaoAceita: declaracao,
122	+            evidencia: evidencia.trim() || null,
123	+            escopo: conferido.escopo,
124	+            ratificarVencido: conferido.vencido ? ratificar : false,
125	+          }
126	+        : null);
127	+    if (!entrada) return;
128	+    envio.current = true;
129	+    setEnviando(true);
130	+    setMensagem(null);
131	+    setPendente(entrada);
132	+    try {
133	+      const r = await f.formalizar(entrada);
134	+      if (!ativo.current) return;
135	+      if (r.ok) {
136	+        setPendente(null);
137	+        setFeito(true);
138	+        setAberto(false);
139	+        setConferido(null);
140	+        setMensagem(r.jaRegistrado ? "Esta formalização já estava registrada — nada foi gravado de novo." : "Aprovação formalizada. Registro auditável gravado.");
141	+        return;
142	+      }
143	+      if (r.code === "fora_do_alvo") return;
144	+      setMensagem(r.mensagem);
145	+      // Recusa CONFERIDA (nada gravado com esta chave) ou chave já usada com outro conteúdo:
146	+      // a próxima tentativa parte de nova conferência, com nova chave e novas declarações.
147	+      if (("naoRegistrada" in r && r.naoRegistrada) || r.code === "idempotencia_conflito") {
148	+        setPendente(null);
149	+        setConferido(null);
150	+        setDeclaracao(false);
151	+        setRatificar(false);
152	+        operacaoId.current = null;
153	+      }
154	+      // Demais (incerto, conflito transitório, sessão/permissão): a MESMA confirmação segue pendente.
155	+    } finally {
156	+      envio.current = false;
157	+      if (ativo.current) setEnviando(false);
158	+    }
159	+  };
160	+
161	+  const escopo = conferido?.escopo ?? null;
162	+  return (
163	+    <div style={{ ...card, marginBottom: 12 }} data-testid="formalizar-aprovacao">
164	+      <div style={{ ...cardTitle, marginBottom: 6 }}>Pagamento registrado com aprovação pendente</div>
165	+      {!aberto ? (
166	+        <>
167	+          <div style={{ fontSize: 11.5, color: C.subtle, lineHeight: 1.5, marginBottom: 8 }}>
168	+            {feito
169	+              ? mensagem
170	+              : "Há pagamento vigente sobre um orçamento ainda não aprovado. Só um administrador pode formalizar a aprovação: um ato novo e auditável, que não altera preço, pagamento, garantia nem entrega."}
171	+          </div>
172	+          {!feito && (
173	+            <button type="button" onClick={abrir} style={btnGhost}>
174	+              Formalizar aprovação pendente
175	+            </button>
176	+          )}
177	+        </>
178	+      ) : (
179	+        <div role="group" aria-label="Formalizar aprovação pendente" style={{ display: "flex", flexDirection: "column", gap: 8, fontSize: 11.5, color: C.body }}>
180	+          {carregando && <div>Conferindo orçamento, título e pagamentos…</div>}
181	+          {escopo && (
182	+            <div style={{ border: `1px solid ${C.line2}`, borderRadius: 8, padding: 9, display: "flex", flexDirection: "column", gap: 4 }}>
183	+              <div style={upLabel}>Escopo conferido no servidor</div>
184	+              <ul style={{ margin: 0, paddingLeft: 16 }}>
185	+                {escopo.orcamento.linhas.map((l, i) => (
186	+                  <li key={`${l.tipo}-${l.id}-${i}`}>{textoLinha(l)}</li>
187	+                ))}
188	+              </ul>
189	+              <div>Total do orçamento: <b>{centavos(escopo.orcamento.totalCentavos)}</b> · revisão {escopo.orcamento.revisao}</div>
190	+              <div>Conta a Receber: <b>{centavos(escopo.titulo.valorCentavos)}</b> ({escopo.titulo.status})</div>
191	+              {escopo.lancamentos.map((l, i) => (
192	+                <div key={i}>{LANCAMENTO[l.tipo]}: {centavos(l.valorCentavos)}</div>
193	+              ))}
194	+              <div>Recebido vigente: <b>{centavos(escopo.recebidoLiquidoCentavos)}</b></div>
195	+            </div>
196	+          )}
197	+          {conferido?.vencido && (
198	+            <label style={{ display: "flex", gap: 6, alignItems: "flex-start", color: C.warnFg }}>
199	+              <input type="checkbox" checked={ratificar} disabled={travado} onChange={(e) => setRatificar(e.target.checked)} />
200	+              <span>O orçamento está vencido. Ratifico neste momento o escopo e o total acima, sem renovar a validade.</span>
201	+            </label>
202	+          )}
203	+          {conferido && (
204	+            <>
205	+              <label>
206	+                <span style={upLabel}>Motivo (obrigatório)</span>
207	+                <textarea
208	+                  aria-label="Motivo da formalização"
209	+                  value={motivo}
210	+                  disabled={travado}
211	+                  onChange={(e) => setMotivo(e.target.value)}
212	+                  maxLength={500}
213	+                  style={{ ...campo, minHeight: 54, resize: "vertical" }}
214	+                />
215	+              </label>
216	+              <label>
217	+                <span style={upLabel}>Referência de evidência (opcional)</span>
218	+                <input aria-label="Referência de evidência" value={evidencia} disabled={travado} onChange={(e) => setEvidencia(e.target.value)} maxLength={300} style={campo} />
219	+              </label>
220	+              <label style={{ display: "flex", gap: 6, alignItems: "flex-start" }}>
221	+                <input type="checkbox" aria-label="Declaração do responsável" checked={declaracao} disabled={travado} onChange={(e) => setDeclaracao(e.target.checked)} />
222	+                <span>{conferido.declaracao}</span>
223	+              </label>
224	+            </>
225	+          )}
226	+          {mensagem && (
227	+            <div role="alert" style={{ color: C.dangerFg }}>
228	+              {mensagem}
229	+            </div>
230	+          )}
231	+          {pendente || conferido ? (
232	+            <button type="button" onClick={() => void formalizar()} disabled={!podeFormalizar || enviando} style={{ ...btnPrimary, opacity: podeFormalizar && !enviando ? 1 : 0.6, cursor: podeFormalizar && !enviando ? "pointer" : "default" }}>
233	+              {enviando ? "Formalizando…" : pendente ? "Reenviar a mesma formalização" : "Formalizar aprovação"}
234	+            </button>
235	+          ) : (
236	+            !carregando && (
237	+              <button type="button" onClick={() => void conferir()} style={btnGhost}>
238	+                Conferir de novo
239	+              </button>
240	+            )
241	+          )}
242	+          <button type="button" onClick={() => { setAberto(false); setMensagem(null); }} disabled={enviando || !!pendente} style={btnGhost}>
243	+            Cancelar
244	+          </button>
245	+        </div>
246	+      )}
247	+    </div>
248	+  );
249	+}
