           <button
             type="button"
             onClick={() => v.abrirCancelamentoComMotivo(v.orcamento.statusLabel === "Recusado" ? "Orçamento recusado pelo cliente." : "Orçamento expirado sem resposta do cliente.")}
             style={{ ...btnGhost, width: "100%" }}
           >
             Cancelar esta OS
           </button>
         </div>
       )}
     </div>
+    </>
   );
 }

