443	+}
444	+
445	+/** Decide sobre o estado TRAVADO; a entrada já passou pela normalização e o replay já foi tratado. */
446	+export function decidirFormalizacaoV3(
447	+  estado: EstadoFormalizacaoV3,
448	+  entrada: EntradaFormalizacaoNormalizadaV3,
449	+): { ok: true; escopo: EscopoFormalizacaoV3; vencido: boolean } | RecusaFormalizacaoV3 {
450	+  const montagem = montarEscopoFormalizacaoV3(estado);
451	+  if (!montagem.ok) return montagem;
452	+  if (canonicoFormalizacaoV3(montagem.escopo) !== canonicoFormalizacaoV3(entrada.escopo)) {
453	+    return recusa(
454	+      "escopo_divergente",
455	+      "O orçamento, a Conta a Receber ou os pagamentos mudaram desde a conferência. Nada foi gravado — confira de novo.",
456	+    );
457	+  }
458	+  if (montagem.vencido && !entrada.ratificarVencido) {
459	+    return recusa("vencido_sem_ratificacao", "O orçamento está vencido: confirme a ratificação no momento atual para formalizar.");
460	+  }
461	+  return montagem;
462	+}
463	+
464	+/**
465	+ * Gravação: orçamento aprovado no instante ATUAL (validade, linhas e totais intactos), registro
466	+ * do ato, nova versão com a natureza e UM evento. Colunas, status técnico, garantia e entrega
467	+ * não mudam (a action grava só o payload).
468	+ */
469	+export function aplicarFormalizacaoV3(
470	+  payload: OrdemServico & Record<string, unknown>,
471	+  p: {
472	+    entrada: EntradaFormalizacaoNormalizadaV3;
473	+    escopo: EscopoFormalizacaoV3;
474	+    vencido: boolean;
475	+    requestFingerprint: string;
476	+    operador: string;
477	+    operadorId: string;
478	+    agora: string;
479	+    eventoId: string;
480	+  },
481	+): { payload: OrdemServico & Record<string, unknown>; registro: RegistroFormalizacaoAprovacaoV3 } {
482	+  const atual = orcamentoRealV3(payload)!;
483	+  const statusAnterior = atual.status as "rascunho" | "enviado";
484	+  const aprovado: OrcamentoV3 = { ...atual, status: "aprovado", respondidoEm: p.agora, atualizadoEm: p.agora };
485	+  const registro: RegistroFormalizacaoAprovacaoV3 = {
486	+    versao: 1,
487	+    natureza: NATUREZA_FORMALIZACAO_APROVACAO_V3,
488	+    atoAtual: true,
489	+    operacaoId: p.entrada.operacaoId,
490	+    requestFingerprint: p.requestFingerprint,
491	+    motivo: p.entrada.motivo,
492	+    declaracao: DECLARACAO_FORMALIZACAO_APROVACAO_V3,
493	+    evidencia: p.entrada.evidencia,
494	+    escopo: p.escopo,
495	+    orcamentoStatusAnterior: statusAnterior,
496	+    validoAte: p.escopo.orcamento.validoAte,
497	+    vencido: p.vencido,
498	+    vencimentoRatificado: p.vencido && p.entrada.ratificarVencido,
499	+    formalizadoPorId: p.operadorId,
500	+    formalizadoPorNome: p.operador,

