const ler = (projection: ReturnType<typeof projecao> | null, extra: { loading?: boolean; error?: string | null; osId?: string } = {}) =>
  derivarSituacaoAtendimentoV4({ osId: extra.osId ?? osId, projection, loading: extra.loading ?? false, error: extra.error ?? null });

describe("situação do atendimento — pagamento ≠ aprovação comercial ≠ entrega", () => {
  it("A1: pagamento verificado e pendência comercial aparecem separados, com uma ação para o comercial", () => {
    const s = ler(projecao());
    expect(s.estado).toBe("pronta");
    expect(s.pagamento).toMatchObject({
      estado: "registrado",
      tom: "success",
      rotulo: "Pagamento registrado — R$ 420,00",
      saldoRotulo: "Saldo do título — R$ 0,00",
      meio: "Dinheiro",
      verificavel: true,
      liquidado: true,
    });
    expect(s.comercial).toMatchObject({ pendente: true, tom: "warning", rotulo: TEXTO_SITUACAO_V4.aprovacaoPendente });
    expect(s.comercial.detalhe).toBe("Orçamento em rascunho · R$ 420,00 · confere com o título");
    expect(s.impedimento).toMatchObject({ codigo: "APROVACAO_COMERCIAL_PENDENTE", destino: "comercial", titulo: "Revisar aprovação comercial", acao: "Abrir orçamento" });
    expect(pagamentoComPendenciaComercialV4(s)).toBe(true);
  });

  it("A2: orçamento aprovado + título liquidado — nenhum impedimento, comercial aprovado", () => {
    const s = ler(projecao({ payload: os("aprovado") }));
    expect(s.impedimento).toBeNull();
    expect(s.comercial).toMatchObject({ pendente: false, rotulo: "Orçamento aprovado", detalhe: "R$ 420,00" });
    expect(s.pagamento).toMatchObject({ estado: "registrado", liquidado: true });
  });

  it("registro de pagamento sem verificação: conferência pendente, nunca selo verde nem valores", () => {
    const s = ler(projecao({ titulo: { ...liquidado, payload: { ordemServicoId: osId, historico: [{ tipo: "liquidacao", valor: 420 }, { tipo: "liquidacao", valor: 420 }] } } }));
    expect(s.pagamento).toMatchObject({ estado: "conferencia_pendente", tom: "warning", rotulo: TEXTO_SITUACAO_V4.conferenciaPendente, verificavel: false, liquidado: false, recebidoLiquido: null, saldoTitulo: null });
    expect(pagamentoComPendenciaComercialV4(s)).toBe(false);
  });

  it("falha real de leitura é o ÚNICO caso de 'Financeiro indisponível'", () => {
    expect(ler(null, { error: "timeout" })).toMatchObject({ estado: "erro", pagamento: { rotulo: TEXTO_SITUACAO_V4.indisponivel }, impedimento: { codigo: "FALHA_LEITURA", destino: "recarregar" } });
    expect(ler(projecao({ falhaLeituraTitulo: true })).pagamento.rotulo).toBe(TEXTO_SITUACAO_V4.indisponivel);
    expect(ler(projecao()).pagamento.rotulo).not.toBe(TEXTO_SITUACAO_V4.indisponivel);
  });

  it("A8: projeção de OUTRA OS (resposta tardia) ou em leitura = carregando, sem fatos nem impedimento", () => {
    expect(ler(projecao(), { osId: "outra-os" })).toMatchObject({ estado: "carregando", impedimento: null, pagamento: { verificavel: false, recebidoLiquido: null } });
    expect(ler(projecao(), { loading: true }).estado).toBe("carregando");
  });

  it("sem título: nenhuma Conta a Receber, sem inventar zero", () => {
    const s = ler(projecao({ titulo: null }));
    expect(s.pagamento).toMatchObject({ estado: "sem_titulo", rotulo: TEXTO_SITUACAO_V4.semTitulo, recebidoLiquido: null, saldoTitulo: null });
    expect(s.impedimento?.codigo).toBe("APROVACAO_COMERCIAL_PENDENTE");
  });

  it("pagamento sem meio identificável não ganha forma inventada", () => {
    const s = ler(projecao({ payload: os("rascunho", { timeline: [] }) }));
    expect(s.pagamento.meio).toBe("Forma não identificada no título");
  });
});

describe("OPS-V4-FINANCEIRO-RETIRADA-GARANTIA-001 — R1: forma de pagamento só pelos fatos", () => {
  it("baixa op-1 + timeline Pix de OUTRA operação: forma não identificada (nunca Pix)", () => {
    const p = projecao({ payload: os("aprovado", { timeline: [{ id: "ev-x", tipo: "operacao_cobranca_gerada", autor: "Op", conteudo: "Pix", criadoEm: "2026-10-05T21:37:38.000Z", metadata: { operacaoId: "op-outra", total: 420, linhas: [{ forma: "pix", valor: 420 }] } }] }) });
    expect(p.paymentMethods.map((m) => m.label)).toEqual(["Pix"]);
    expect(formaRegistradaV4(p, "Pix")).toBe("Forma não identificada no título");
  });

  it("título em conferência = 'Em conferência'; sem título = 'Não registrada'; falha = 'Indisponível'", () => {
    expect(formaRegistradaV4(projecao({ titulo: { ...liquidado, payload: { ordemServicoId: osId, historico: [{ tipo: "liquidacao", valor: 420 }, null] } } }), "Dinheiro")).toBe("Em conferência");
    expect(formaRegistradaV4(projecao({ titulo: null }), "Dinheiro")).toBe("Não registrada");
    expect(formaRegistradaV4(projecao({ falhaLeituraTitulo: true }), "Dinheiro")).toBe("Indisponível");
    expect(formaRegistradaV4(projecao(), "x")).toBe("Dinheiro");
  });
});

describe("OPS-V4-FINANCEIRO-RETIRADA-GARANTIA-001 — R3: regra única de afirmação e meios com valor próprio", () => {
  const titulo = (status: string, historico: unknown[]) => ({ ...liquidado, status, payload: { ordemServicoId: osId, historico } });
  const evento = (linhas: unknown[]) => ({ id: "ev-1", tipo: "operacao_cobranca_gerada", autor: "Op", conteudo: "Recebimento", criadoEm: "2026-10-05T21:37:38.000Z", metadata: { operacaoId: "op-1", total: 420, linhas } });

  it("afirmação dos valores do título: carregando / indisponível / conferência / afirmável — conferência em QUALQUER status legado", () => {
    expect(afirmacaoValoresTituloV4(ler(projecao(), { loading: true }))).toBe("carregando");
    expect(afirmacaoValoresTituloV4(ler(projecao(), { osId: "outra-os" }))).toBe("carregando");
    expect(afirmacaoValoresTituloV4(ler(null, { error: "Falha de rede." }))).toBe("indisponivel");
    expect(afirmacaoValoresTituloV4(ler(projecao({ falhaLeituraTitulo: true })))).toBe("indisponivel");
    const duas = projecao({ payload: os("aprovado"), titulo: titulo("pago", [{ tipo: "pagamento", valor: 300, loteId: "a" }, { tipo: "pagamento", valor: 300, loteId: "b" }]) });
    expect(duas.financialStatus).toBe("INCONSISTENT");
    expect(afirmacaoValoresTituloV4(ler(duas))).toBe("conferencia");
    expect(pagamentoEmConferenciaV4(ler(duas))).toBe(true);
    const cancelado = projecao({ payload: os("aprovado"), titulo: titulo("cancelado", [{ tipo: "pagamento", valor: 100, loteId: "a" }]) });
    expect(afirmacaoValoresTituloV4(ler(cancelado))).toBe("conferencia");
    expect(afirmacaoValoresTituloV4(ler(projecao()))).toBe("afirmavel");
    expect(afirmacaoValoresTituloV4(ler(projecao({ titulo: null })))).toBe("afirmavel");
  });

  it("R3-P2: split Pix R$ 100 com o resto sem linha mostra as duas partes; split completo mostra cada valor; meio único mostra só o rótulo", () => {
    expect(ler(projecao({ payload: os("rascunho", { timeline: [evento([{ forma: "pix", valor: 100 }])] }) })).pagamento.meio)
      .toBe("Pix R$ 100,00 + forma não identificada R$ 320,00");
    expect(ler(projecao({ payload: os("rascunho", { timeline: [evento([{ forma: "pix", valor: 100 }, { forma: "dinheiro", valor: 320 }])] }) })).pagamento.meio)
      .toBe("Pix R$ 100,00 + Dinheiro R$ 320,00");
    expect(ler(projecao()).pagamento.meio).toBe("Dinheiro");
    // valor malformado na linha: nada de Pix R$ 420
    expect(ler(projecao({ payload: os("rascunho", { timeline: [evento([{ forma: "pix", valor: [420] }])] }) })).pagamento.meio)
      .toBe("Forma não identificada no título");
  });
});

describe("GOAL OPS-V4-FINANCEIRO-RETIRADA-GARANTIA-002 — oferta de 'Aprovar e receber' (C) e da formalização (D)", () => {
  const orcamentoBase = { id: "orc", sintetizado: false, total: 420, desconto: 0, servicos: [{ id: "s1", descricao: "Troca de Tela", valor: 420 }], pecas: [], criadoEm: "2026-09-18T10:00:00.000Z" };
  const aberto = { id: "cr", storeId, localKey, valor: 420, status: "pendente", payload: { ordemServicoId: osId, historico: [] } };
  const oferta = (s: ReturnType<typeof ler>) => ({ formalizar: podeOferecerFormalizacaoV4(s), aprovarEReceber: podeOferecerAprovarEReceberV4(s) });

  it("rascunho + título liquidado verificável: formalização; nunca 'Aprovar e receber' (seria 2ª cobrança)", () => {
    expect(oferta(ler(projecao()))).toEqual({ formalizar: true, aprovarEReceber: false });
  });

  it("pagamento parcial vigente sobre rascunho também é caso de formalização", () => {
    const parcial = { ...liquidado, status: "parcial", payload: { ordemServicoId: osId, historico: [{ tipo: "pagamento", valor: 100, loteId: "op-1" }] } };
    expect(oferta(ler(projecao({ titulo: parcial })))).toEqual({ formalizar: true, aprovarEReceber: false });
  });

  it("enviado vencido com pagamento: formalização (a ratificação é exigida no servidor)", () => {
    const p = projecao({ payload: os("enviado", { orcamento: { ...orcamentoBase, status: "enviado", validoAte: "2026-10-01T02:59:59.000Z" } }) });
    expect(p.acoes?.impedimento?.codigo).toBe("ORCAMENTO_EXPIRADO");
    expect(oferta(ler(p))).toEqual({ formalizar: true, aprovarEReceber: false });
  });

  it("rascunho sem título ou com título sem pagamento: 'Aprovar e receber'; nada a formalizar", () => {
    expect(oferta(ler(projecao({ titulo: null })))).toEqual({ formalizar: false, aprovarEReceber: true });
    expect(oferta(ler(projecao({ titulo: aberto })))).toEqual({ formalizar: false, aprovarEReceber: true });
  });

  it("histórico em conferência, aprovado, recusado, carregando ou outra OS: nenhuma das duas", () => {
    const ilegivel = { ...liquidado, payload: { ordemServicoId: osId, historico: [{ tipo: "pagamento", valor: "abc" }] } };
    const casos = [
      ler(projecao({ titulo: ilegivel })),
      ler(projecao({ payload: os("aprovado", { orcamento: { ...orcamentoBase, status: "aprovado", respondidoEm: "2026-09-19T10:00:00.000Z" } }) })),
      ler(projecao({ payload: os("recusado") })),
      ler(projecao(), { loading: true }),
      ler(projecao(), { osId: "outra-os" }),
    ];
    for (const s of casos) expect(oferta(s)).toEqual({ formalizar: false, aprovarEReceber: false });
  });
});

describe("GOAL OPS-V4-FINANCEIRO-RETIRADA-GARANTIA-002 — orientação antes de 'Gerar orçamento' (B)", () => {
  it("pagamento verificado (quitado ou parcial) orienta com o MESMO texto da recusa do servidor", () => {
    expect(orientacaoGerarOrcamentoV4(ler(projecao()))).toBe(MENSAGEM_GERAR_ORCAMENTO_COM_PAGAMENTO_V3);
    const parcial = { ...liquidado, status: "parcial", payload: { ordemServicoId: osId, historico: [{ tipo: "pagamento", valor: 100, loteId: "op-1" }] } };
    expect(orientacaoGerarOrcamentoV4(ler(projecao({ titulo: parcial })))).toBe(MENSAGEM_GERAR_ORCAMENTO_COM_PAGAMENTO_V3);
    const semOrcamento = projecao({ payload: os("rascunho", { orcamento: undefined }) });
    expect(orientacaoGerarOrcamentoV4(ler(semOrcamento))).toBe(MENSAGEM_GERAR_ORCAMENTO_COM_PAGAMENTO_V3);
  });

  it("histórico do título em conferência orienta a conferir a Conta a Receber", () => {
    const ilegivel = { ...liquidado, payload: { ordemServicoId: osId, historico: [{ tipo: "pagamento", valor: "abc" }] } };
    expect(orientacaoGerarOrcamentoV4(ler(projecao({ titulo: ilegivel })))).toBe(MENSAGEM_GERAR_ORCAMENTO_PAGAMENTOS_EM_CONFERENCIA_V3);
  });

  it("sem título, título sem pagamento, carregando ou outra OS: nada a orientar (segue ao servidor, que decide)", () => {
    const aberto = { id: "cr", storeId, localKey, valor: 420, status: "pendente", payload: { ordemServicoId: osId, historico: [] } };
    for (const s of [ler(projecao({ titulo: null })), ler(projecao({ titulo: aberto })), ler(projecao(), { loading: true }), ler(projecao(), { osId: "outra-os" })]) {
      expect(orientacaoGerarOrcamentoV4(s)).toBeNull();
    }
  });
});

