2	//
3	// OPS-V4-FINANCEIRO-RETIRADA-GARANTIA-002 — PostgreSQL REAL, local e descartável.
4	// Writers REAIS da V3 (receber, misto, a prazo, estorno, aprovar, gerar orçamento, atendimento
5	// rápido, abertura autorizada) e a ação nova de formalização, contra o banco. Só a SESSÃO
6	// (`@/auth`) e `next/cache` são simulados; a permissão é a matriz REAL por papel. Concorrência
7	// por barreira na escrita + espera de trava confirmada no `pg_stat_activity` (nunca sleep).
8	// Ausência de banco = BLOQUEIO_EXPLICITO_PG (nunca skip). Massa sintética (`qa-frg2-*`).
9	import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
10	
11	const sessao = vi.hoisted(() => ({
12	  id: "qa-frg2-admin",
13	  name: "Admin QA FRG2",
14	  role: "ADMIN",
15	  storeAccess: "all" as string,
16	  allowedStoreIds: [] as string[],
17	}));
18	vi.mock("@/auth", () => ({ auth: vi.fn(async () => ({ user: { ...sessao } })) }));
19	vi.mock("next/cache", () => ({ revalidatePath: vi.fn() }));
20	
21	// Barreira na escrita (mesmo padrão de `test/ops-v3-recebimento-misto/hardening-p1-transitivos.pg.ts`):
22	// a transação real para DEPOIS de gravar, segurando as travas, até o teste liberar.
23	type Fase = "antes" | "depois";
24	type Pausa = {
25	  modelo: string;
26	  metodos: readonly string[];
27	  fase: Fase;
28	  quando: (args: unknown, resultado?: unknown) => boolean;
29	  chegou: () => void;
30	  barreira: Promise<void>;
31	};
32	const intercept = vi.hoisted(() => ({ pausa: null as null | Pausa }));
33	
34	vi.mock("@/lib/prisma", async (importOriginal) => {
35	  const real = await importOriginal<typeof import("@/lib/prisma")>();
36	  const envolverDelegate = (modelo: string, delegate: object) =>
37	    new Proxy(delegate, {
38	      get(t, p) {
39	        const fn = Reflect.get(t, p);
40	        if (typeof fn !== "function") return fn;
41	        return async (args: unknown) => {
42	          const pausa = intercept.pausa;
43	          const alvo = pausa && pausa.modelo === modelo && pausa.metodos.includes(String(p));
44	          if (alvo && pausa.fase === "antes" && pausa.quando(args)) {
45	            intercept.pausa = null;
46	            pausa.chegou();
47	            await pausa.barreira;
48	          }
49	          const r = await (fn as (a: unknown) => Promise<unknown>).call(t, args);
50	          if (alvo && pausa.fase === "depois" && intercept.pausa === pausa && pausa.quando(args, r)) {
