254	async function esperarBloqueioNoBanco(timeoutMs = 15_000, minimo = 1): Promise<void> {
255	  const fim = Date.now() + timeoutMs;
256	  while (Date.now() < fim) {
257	    const rows = await prisma.$queryRaw<Array<{ n: number }>>`
258	      SELECT count(*)::int AS n FROM pg_stat_activity
259	      WHERE datname = current_database() AND wait_event_type = 'Lock' AND pid <> pg_backend_pid()
260	    `;
261	    if ((rows[0]?.n ?? 0) >= minimo) return;
262	    await new Promise((r) => setTimeout(r, 25));
263	  }
264	  throw new Error("a operação concorrente não chegou a esperar a trava");
265	}
