260	+async function esperarBloqueioNoBanco(timeoutMs = 15_000, minimo = 1): Promise<void> {
261	+  const fim = Date.now() + timeoutMs;
262	+  while (Date.now() < fim) {
263	+    const rows = await prisma.$queryRaw<Array<{ n: number }>>`
264	+      SELECT count(*)::int AS n FROM pg_stat_activity
265	+      WHERE datname = current_database() AND wait_event_type = 'Lock' AND pid <> pg_backend_pid()
266	+    `;
267	+    if ((rows[0]?.n ?? 0) >= minimo) return;
268	+    await new Promise((r) => setTimeout(r, 25));
269	+  }
270	+  throw new Error("a operação concorrente não chegou a esperar a trava");
