273	+/** Resolve quando a promessa termina OU quando outra transação está esperando trava no banco. */
274	+async function concluiuOuEsperaTrava(p: Promise<unknown>): Promise<"concluiu" | "esperando_trava"> {
275	+  return Promise.race([p.then(() => "concluiu" as const, () => "concluiu" as const), esperarBloqueioNoBanco().then(() => "esperando_trava" as const)]);
276	+}
277	+
278	+function armarPausa(p: { modelo: string; metodos: readonly string[]; fase?: Fase; quando: (args: Payload, resultado?: unknown) => boolean }) {
279	+  let liberar!: () => void;
280	+  const barreira = new Promise<void>((r) => (liberar = r));
281	+  let chegou!: () => void;
