286	+    fase: p.fase ?? "depois",
287	+    quando: (args, r) => !!args && typeof args === "object" && p.quando(args as Payload, r),
288	+    chegou,
289	+    barreira,
290	+  };
291	+  return { naBarreira, liberar };
292	+}
