import {
  buildVals,
  type AprovacaoNoRecebimentoV4,
  type ConferenciaFormalizacaoUiV4,
  type FormalizacaoAprovacaoUiV4,
  type RecebimentoAposAprovacaoV4,
  type ResultadoAprovarEReceberV4,
  type V4DataCtx,
