import { OrcamentoDecisaoCluster } from "@/components/operacoes-v4-preview/parts/stages/OrcamentoDecisaoCluster";
import { ReceberPagamentoV4 } from "@/components/operacoes-v4-preview/parts/ReceberPagamentoV4";
