 frg: { db: "ops_v4_frg_qa_002", bootstrap: "test/ops-v4-financeiro-retirada-garantia-001/qa-bootstrap.mjs", specs: ["e2e/specs/ops-v4-financeiro-retirada-garantia-002.spec.ts"] },
