 let output = "";
 for (const stream of [child.stdout, child.stderr]) stream.on("data", chunk => { output += chunk; process.stdout.write(chunk); });
 const code = await new Promise((resolve, reject) => { child.once("error", reject); child.once("exit", resolve); });
