13	const LOJA = "000-qa-frg-001";
14	/**
15	 * Espera de um ESTADO que depende de várias idas ao servidor encadeadas (salvar → reler →
16	 * abrir → conferir; aprovar → receber → reler). Sob máquina carregada passa dos 25 s padrão;
17	 * continua sendo espera pelo fato, nunca um tempo fixo.
18	 */
19	const IDA_E_VOLTA = { timeout: 60_000 };
20	const ENTRADA = "2026-09-18T12:00:00.000Z";
21	
22	function bancoDescartavel(): string {
23	  const urls = [process.env.DATABASE_URL, process.env.DIRECT_URL].map((v) => (v ?? "").trim());
24	  if (urls.some((v) => !v)) throw new Error("E2E FRG-002 exige DATABASE_URL e DIRECT_URL locais descartáveis.");
25	  const parsed = urls.map((v) => new URL(v));
26	  if (parsed.some((u) => !["127.0.0.1", "localhost", "::1", "[::1]"].includes(u.hostname))) {
27	    throw new Error("E2E FRG-002 só aceita PostgreSQL em loopback.");
28	  }
29	  if (parsed[0]!.href !== parsed[1]!.href || !parsed[0]!.pathname.slice(1).startsWith("ops_v4_frg_qa")) {
30	    throw new Error("E2E FRG-002 exige URLs idênticas do banco descartável ops_v4_frg_qa*.");
31	  }
32	  return urls[0]!;
33	}
