39	
40	/** OS pronta com orçamento no status pedido (ou sem orçamento) e, opcional, título liquidado pela MESMA operação. */
41	async function semearOS(prisma: PrismaClient, orc: Orc, pago: boolean): Promise<{ id: string; codigo: string }> {
42	  const m = marca();
43	  const id = `qa-frg2-${m}`;
44	  const codigo = `OS-QA-FRG2-${m}`;
45	  const operacaoId = `op-qa-frg2-${m}`;
46	  const quitacao = {
47	    id: `ev-quit-${m}`, tipo: "operacao_cobranca_gerada", autor: "Operador QA FRG2", autorTipo: "usuario",
48	    conteudo: "Quitação: Dinheiro R$ 420,00 (total R$ 420.00) · saldo R$ 0.00 (quitado).", criadoEm: "2026-10-05T21:37:38.000Z",
49	    metadata: { operacaoId, total: 420, linhas: [{ forma: "dinheiro", valor: 420 }], op: "liquidar", intencao: "quitacao" },
50	  };
51	  await prisma.ordemServico.create({
52	    data: {
53	      id, storeId: LOJA, numero: codigo, status: "Pronto", equipamento: "Samsung S20 FE", defeito: "Tela quebrada", valorTotal: 420,
54	      payload: {
55	        id, codigo, storeId: LOJA, clienteId: "", criadoEm: ENTRADA, atualizadoEm: ENTRADA, prioridade: "media", origem: "balcao",
56	        pecas: [], observacoes: [], anexos: [],
57	        cliente: { id: "", nome: `Cliente QA FRG2 ${m}` },
58	        equipamento: { tipo: "Smartphone", marca: "Samsung", modelo: "S20 FE", defeitoRelatado: "Tela quebrada", acessorios: ["Capa"] },
59	        status: "pronta", operacaoStatus: "pronta", operacaoStatusV3: "pronta", valorTotal: 420,
60	        ...(orc
61	          ? {
62	              orcamento: {
63	                id: `orc-${m}`, status: orc, sintetizado: false, criadoEm: ENTRADA, ...(orc === "aprovado" ? { respondidoEm: ENTRADA } : {}),
64	                desconto: 0, total: 420, servicos: [{ id: "s1", descricao: "Troca de Tela", valor: 420 }], pecas: [],
65	              },
66	            }
67	          : {}),
68	        aberturaV3: { versao: 1, recepcao: { recebidoPor: "Balcão QA", origem: "balcao", prioridade: "media", localFisico: "balcao", dataEntrada: ENTRADA }, garantiaPrevista: { modelo: "tela", prazoDias: 90 } },
69	        timeline: [
70	          { id: `ev-${m}`, tipo: "criacao", autor: "QA", autorTipo: "usuario", conteudo: "OS criada.", criadoEm: ENTRADA },
71	          ...(pago ? [quitacao] : []),
72	        ],
73	      } as unknown as Prisma.InputJsonValue,
74	    },
75	  });
76	  if (pago) {
