15	  if (parsed[0]!.href !== parsed[1]!.href || !parsed[0]!.pathname.slice(1).startsWith("ops_v3_misto_qa")) throw new Error("E2E exige URLs idênticas do banco descartável ops_v3_misto_qa*.");
