+      timeline: [],
+    },
+  });
+  const localKey = localKeyContaReceberOSV3(SID, OS);
+  h.titulos.set(`${SID}::${localKey}`, {
+    id: "cr-1",
+    storeId: SID,
+    localKey,
+    valor: 420,
+    status: "pago",
+    payload: { ordemServicoId: OS, historico: [{ tipo: "liquidacao", valor: 420, loteId: "op-1" }] },
+  });
