+    expect(await formalizarAprovacaoPendenteV3(SID, OS, entrada(escopo, { operacaoId: "op-formaliza-2" }))).toMatchObject({ ok: false, code: "nao_pendente" });
+    expect(h.updates).toHaveLength(1);
