    const escopo = await conferir();
    h.sql.length = 0;
    expect(await formalizarAprovacaoPendenteV3(SID, OS, entrada(escopo, { declaracaoAceita: false }))).toMatchObject({ ok: false, code: "entrada_invalida", naoRegistrada: true });
