    vi.clearAllMocks();
    ordemTx.length = 0;
    // Outra operação já recusou o orçamento: a releitura sob a trava enxerga isso.
    findFirstMock.mockResolvedValue(baseRow({ status: "recusado", servicos: [{ id: "s1", descricao: "Serviço", valor: 100 }] }));
