27	  function put(row: Row): Row {
28	    titulos.set(ck(row.storeId, row.localKey), row);
29	    byId.set(row.id, row);
30	    return row;
31	  }
32	  function makeRow(data: any): Row {
33	    const storeId = data.storeId ?? data?.store?.connect?.id;
34	    return {
35	      id: `cr-${++seq}`,
36	      storeId,
37	      localKey: data.localKey,
38	      descricao: data.descricao ?? "",
39	      cliente: data.cliente ?? "",
40	      valor: data.valor ?? 0,
41	      vencimento: data.vencimento ?? "",
42	      status: data.status ?? "pendente",
43	      payload: data.payload ?? {},
44	      createdAt: tick(),
45	      updatedAt: tick(),
46	    };
47	  }
48	  function applyScalars(row: Row, data: any): Row {
49	    for (const k of ["descricao", "cliente", "valor", "vencimento", "status", "payload"]) {
50	      if (data[k] !== undefined) row[k] = data[k];
51	    }
52	    row.updatedAt = tick();
53	    return row;
54	  }
55	  function snapshot(row: Row | null | undefined): Row | null {
56	    return row ? { ...row } : null;
57	  }
