59	  // Ganchos de teste: rodam quando a action pede a trava por OS (advisory lock) — simulam
60	  // outra operação que commitou enquanto esta esperava a trava.
61	  const aoTravarOS: Array<() => void> = [];
62	
63	  const prisma: any = {
