39	}
40	
41	describe("centavos estritos — valor inválido nunca é arredondado para caber", () => {
42	  it("aceita até 2 casas e rejeita negativo, NaN e 3 casas", () => {
43	    expect(centavosEstritosV3(350)).toBe(35000);
44	    expect(centavosEstritosV3(0.1 + 0.2)).toBe(30);
45	    expect(centavosEstritosV3(-1)).toBeNull();
