52	    expect(parseValorDigitadoV3("350,00")).toBe(35000);
53	    expect(parseValorDigitadoV3("1.234,56")).toBe(123456);
54	    expect(parseValorDigitadoV3("50.5")).toBe(5050);
55	    expect(parseValorDigitadoV3("")).toBeNull();
56	    expect(parseValorDigitadoV3("   ")).toBeNull();
57	    expect(parseValorDigitadoV3("-50")).toBeNull();
58	    expect(parseValorDigitadoV3("abc")).toBeNull();
59	    expect(parseValorDigitadoV3("10,005")).toBeNull();
60	  });
61	});
62	
63	describe("vencimento — data civil sem conversão de fuso", () => {
64	  it("rejeita ausente, inexistente, formato com hora e data anterior a hoje", () => {
