288	async function esperarBloqueioNoBanco(timeoutMs = 15_000, minimo = 1): Promise<void> {
289	  const fim = Date.now() + timeoutMs;
290	  while (Date.now() < fim) {
291	    const rows = await prisma.$queryRaw<Array<{ n: number }>>`
292	      SELECT count(*)::int AS n FROM pg_stat_activity
293	      WHERE datname = current_database() AND wait_event_type = 'Lock' AND pid <> pg_backend_pid()
294	    `;
295	    if ((rows[0]?.n ?? 0) >= minimo) return;
296	    await new Promise((r) => setTimeout(r, 25));
297	  }
298	  throw new Error("a operação concorrente não chegou a esperar a trava");
299	}
