306	function armarPausa(p: { modelo: string; metodos: readonly string[]; fase?: Fase; quando: (args: Payload, resultado?: unknown) => boolean }) {
307	  let liberar!: () => void;
308	  const barreira = new Promise<void>((r) => (liberar = r));
309	  let chegou!: () => void;
310	  const naBarreira = new Promise<void>((r) => (chegou = r));
311	  intercept.pausa = {
312	    modelo: p.modelo,
313	    metodos: p.metodos,
314	    fase: p.fase ?? "antes",
315	    quando: (args, r) => !!args && typeof args === "object" && p.quando(args as Payload, r),
316	    chegou,
317	    barreira,
318	  };
319	  let liberada = false;
320	  return {
321	    naBarreira,
322	    liberar: () => {
323	      if (liberada) return;
324	      liberada = true;
325	      liberar();
326	    },
327	  };
328	}
