1	/**
2	 * OPS-RECEBIMENTO-MISTO-P1-HARDENING-001 — tela REAL montada (jsdom) com o hook REAL.
3	 *
4	 * P1-A (T08): resposta perdida no PIX 100 → saldo relido 300 → o operador representa a MESMA
5	 * confirmação como PIX 50 + PIX 50. A chave econômica tem de ser a mesma (replay), nunca uma
6	 * segunda baixa. Um recebimento NOVO legítimo depois (PIX 20) continua permitido.
7	 *
8	 * P2 (T18/T19): a resposta da OS A chega quando o operador já está na OS B — nada do rascunho
9	 * de B pode ser apagado nem recarregado por causa de A.
10	 *
11	 * O "servidor" aqui é um fake com ledger mínimo (replay por operacaoId + saldo esperado), só
12	 * para tornar a baixa em dobro OBSERVÁVEL; o servidor real é provado no PostgreSQL.
13	 */
14	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
15	import { act, cleanup, fireEvent, render, screen, waitFor, within } from "@testing-library/react";
16	import type { OrdemServico } from "@/types/os";
17	
18	const mocks = vi.hoisted(() => ({
19	  lerPagamentoOSV3: vi.fn(),
20	  receberOSV3: vi.fn(),
21	  estornarRecebimentoOSV3: vi.fn(),
22	  registrarRecebimentoMistoOSV3: vi.fn(),
23	}));
24	vi.mock("@/lib/operacoes-v3/pdv-servico-actions", () => mocks);
25	
26	import { PdvServicoV3 } from "@/components/operacoes-v3/pages/PdvServicoV3";
27	import { OperacoesV3Context, type OperacoesV3ContextValue } from "@/components/operacoes-v3/context/OperacoesV3Context";
28	
29	const VENC = "2099-12-31";
30	const txt = (s: string | null | undefined) => (s ?? "").replace(/ /g, " ");
31	const valorDe = (label: string | RegExp) => (screen.getByLabelText(label) as HTMLInputElement).value;
32	
33	function os(id: string, codigo: string): OrdemServico {
34	  return {
35	    id,
36	    codigo,
37	    status: "pronta",
38	    operacaoStatusV3: "pronta",
39	    cliente: { nome: `Cliente ${codigo}` },
40	    equipamento: { tipo: "Smartphone", marca: "Samsung", modelo: "A54" },
41	    orcamento: {
42	      id: `orc-${id}`,
43	      status: "aprovado",
44	      pecas: [],
45	      servicos: [{ id: "s1", descricao: "Troca de tela", valor: 400 }],
46	      desconto: 0,
47	      total: 400,
48	      criadoEm: "2026-10-01T12:00:00.000Z",
49	    },
50	  } as unknown as OrdemServico;
51	}
52	
53	const ctxBase = (ordens: OrdemServico[], selectedOsId: string): OperacoesV3ContextValue => ({
54	  storeId: "loja-qa",
55	  activeScreen: "pdv-servico",
56	  selectedOsId,
57	  navigate: vi.fn(),
58	  openOS: vi.fn(),
59	  ordens,
60	  loading: false,
61	  primeiraCarga: false,
62	  error: null,
63	  reload: vi.fn(),
64	  mudarStatus: vi.fn(async () => true),
65	  abrirNovaOS: vi.fn(),
66	  notificar: vi.fn(),
67	  acaoEmConstrucao: vi.fn(),
68	});
69	
70	function leitura(over: Record<string, unknown> = {}) {
71	  return { total: 400, recebido: 0, saldo: 400, status: "aberto", sessao: { aberta: true, sessaoId: "sessao-1", operador: "Caixa QA" }, aPrazo: null, ...over };
72	}
73	
74	function recibo(valorPago: number, saldoRestante: number) {
75	  return {
76	    numeroOS: "OS-A",
77	    cliente: "Cliente OS-A",
78	    equipamento: "Samsung A54",
79	    formas: [{ forma: "pix", label: "PIX", valor: valorPago }],
80	    intencaoLabel: "Parcial",
81	    valorPago,
