130	 * Servidor fake com ledger: mesma `operacaoId` já gravada → replay (sem nova baixa); chave nova
131	 * só grava contra o saldo que o operador viu. `perderResposta` grava e "perde" a resposta.
132	 */
133	function servidorComLedger(saldoInicial = 400) {
134	  const estado = { saldo: saldoInicial, baixas: [] as Array<{ operacaoId: string; centavos: number }>, perderResposta: false };
135	  const gravadas = new Map<string, number>();
136	  mocks.lerPagamentoOSV3.mockImplementation(async () => leitura({ recebido: saldoInicial - estado.saldo, saldo: estado.saldo }));
137	  mocks.receberOSV3.mockImplementation(async (_sid: string, _osId: string, input: { operacaoId: string; saldoEsperado?: number; valor?: number; linhas?: Array<{ valor: number }> }) => {
138	    const centavos = Math.round((input.linhas ? input.linhas.reduce((a, l) => a + l.valor, 0) : input.valor ?? 0) * 100);
139	    const resposta = (jaRegistrado: boolean) => ({
140	      os: {},
141	      pagamento: { total: 400, recebido: saldoInicial - estado.saldo, saldo: estado.saldo, status: "parcial" },
142	      valorRecebido: centavos / 100,
143	      op: "parcial",
144	      recibo: recibo(centavos / 100, estado.saldo),
145	      operacaoId: input.operacaoId,
146	      jaRegistrado,
147	    });
148	    if (gravadas.has(input.operacaoId)) return resposta(true);
149	    if (Math.round((input.saldoEsperado ?? -1) * 100) !== Math.round(estado.saldo * 100)) {
150	      throw new Error(`O saldo desta OS mudou (agora R$ ${estado.saldo.toFixed(2)}). Atualize e confirme de novo.`);
151	    }
152	    estado.saldo = Math.round(estado.saldo * 100 - centavos) / 100;
153	    estado.baixas.push({ operacaoId: input.operacaoId, centavos });
154	    gravadas.set(input.operacaoId, centavos);
155	    if (estado.perderResposta) {
156	      estado.perderResposta = false;
157	      throw new Error("Failed to fetch");
158	    }
159	    return resposta(false);
160	  });
161	  return estado;
162	}
