28	function exigirBancoLocal(): void {
29	  const urls = [process.env.OPS_V4_FRG_TEST_DATABASE_URL, process.env.DATABASE_URL, process.env.DIRECT_URL].map((v) => (v ?? "").trim());
30	  if (urls.some((v) => !v)) {
31	    throw new Error("BLOQUEIO_EXPLICITO_PG: configure OPS_V4_FRG_TEST_DATABASE_URL + DATABASE_URL + DIRECT_URL para o PostgreSQL local descartável.");
32	  }
33	  const alvos = urls.map((v) => new URL(v));
34	  if (alvos.some((u) => !["127.0.0.1", "localhost", "::1", "[::1]"].includes(u.hostname.toLowerCase()))) {
35	    throw new Error("BLOQUEIO_EXPLICITO_PG: integração só pode usar loopback.");
36	  }
37	  const chave = (u: URL) => `${u.hostname}:${u.port}${u.pathname}`;
38	  if (alvos.some((u) => chave(u) !== chave(alvos[0]!)) || !alvos[0]!.pathname.slice(1).startsWith("ops_v4_frg_qa")) {
39	    throw new Error("BLOQUEIO_EXPLICITO_PG: as três URLs devem apontar ao MESMO banco descartável ops_v4_frg_qa*.");
40	  }
41	}
